//! Linking on macOS through `ld64.lld` directly, without the Clang driver, Apple's `ld`
//! nor the Command Line Tools (or Xcode) on the machine of whoever uses
//! dartforge (N16).
//!
//! The Clang driver only gave the link the root of the macOS SDK (found by
//! `xcrun`), where the `.tbd` *stubs* of the system libraries come from
//! (`libSystem` and the `CoreFoundation` and `Security` frameworks), and the platform
//! versions. Here the `.tbd` files are **generated by dartforge**
//! ([`SYSTEM_LIBRARIES`], [`gerar`]), like the import libraries
//! of Windows (`ligador_windows.rs`): nothing from Apple's SDK is copied or
//! redistributed — its license (Xcode and Apple SDKs Agreement) does not
//! allow it. A `.tbd` is text (YAML, TAPI v4 format): the install path
//! of the library and the names it exports; a name is an interface fact.
//! The program loads the system libraries when it runs.
//!
//! The generated files live in a **link sysroot** ([`SysrootMacos`]): the
//! distribution one (`lib/sysroot/<arch>-apple-darwin/`, generated by
//! `dartforge empacotar`) or, in a development tree, the native cache,
//! generated once per content.

use std::path::{Path, PathBuf};
use std::process::Command;

/// The macOS architectures.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Arquitetura {
    Arm64,
    X86_64,
}

impl Arquitetura {
    /// That of this host.
    pub const fn do_hospedeiro() -> Arquitetura {
        if cfg!(target_arch = "aarch64") { Arquitetura::Arm64 } else { Arquitetura::X86_64 }
    }

    /// The triple of the sysroot (`lib/sysroot/<triple>`).
    pub const fn triple_do_sysroot(self) -> &'static str {
        match self {
            Arquitetura::Arm64 => "arm64-apple-darwin",
            Arquitetura::X86_64 => "x86_64-apple-darwin",
        }
    }

    /// The name in the `-arch` of `ld64.lld`.
    const fn name(self) -> &'static str {
        match self {
            Arquitetura::Arm64 => "arm64",
            Arquitetura::X86_64 => "x86_64",
        }
    }

    /// The minimum macOS version: that of `rustc` for the target.
    const fn minimum(self) -> &'static str {
        match self {
            Arquitetura::Arm64 => "11.0",
            Arquitetura::X86_64 => "10.12",
        }
    }
}

/// The sysroot triple of this host.
pub fn triple_do_sysroot() -> &'static str {
    Arquitetura::do_hospedeiro().triple_do_sysroot()
}

/// A system library and the names the link asks of it.
pub struct SystemLibrary {
    /// The `.tbd`, relative to the sysroot: the name `ld64.lld` looks it up by
    /// (`-lSystem` → `usr/lib/libSystem.tbd`; `-framework X` →
    /// `System/Library/Frameworks/X.framework/X.tbd`).
    pub file: &'static str,
    /// The install path, written into the executable (`LC_LOAD_DYLIB`).
    pub install_name: &'static str,
    /// The names (with the Mach-O `_`) on both architectures.
    pub symbols: &'static [&'static str],
    /// Those only arm64 uses.
    pub arm64_only: &'static [&'static str],
    /// Those only x86-64 uses: the suffixed variants the SDK headers
    /// choose there (`$INODE64`, `$NOCANCEL`).
    pub x86_64_only: &'static [&'static str],
}

/// The system libraries and the names that the runtime (both `staticlib`s),
/// the SDK and the generated code use. `libSystem` reexports those of
/// `/usr/lib/system/` (`libsystem_c`, `libsystem_kernel`, `libdyld`,
/// `libunwind`, `libdispatch`, `libcommonCrypto`, `libsystem_m`…): the
/// executable links only with it, and `dyld` finds each name through the reexports.
///
/// The runtime list came from the `nm` of the `staticlib`s (`arm64` and `x86_64`, `aot`
/// and `dll`) and from what `ld64.lld` required when linking, on macOS, everything a
/// program may pull from them: Rust compiles a crate into few objects, and
/// pulling a name brings the whole object with everything it cites (hence the
/// almost entire `security_framework`). The tests
/// `runtime_only_uses_listed_symbols` and `symbols_exist_in_sdk` check,
/// on the macOS runner (arm64), that nothing is missing and that each name exists in the SDK;
/// the x86-64 variants (`x86_64_only`) have no runner to check them.
