/// The system libraries, in the `ld64.lld` format.
const LIBRARIES: &[&str] = &["-lSystem", "-framework", "CoreFoundation", "-framework", "Security"];

/// The file with the SDK version (the `-platform_version`) of the sysroots that
/// copied the SDK `.tbd` files; in the generated ones it does not exist, and the version is the
/// minimum.
const VERSION_FILE: &str = "versao-do-sdk";

/// The `.tbd` (TAPI v4) of `b` for `arch`.
///
/// ```
/// use dartforge_emit_native::ligador_macos::{Arquitetura, SYSTEM_LIBRARIES, tbd};
/// let text = tbd(&SYSTEM_LIBRARIES[0], Arquitetura::Arm64);
/// assert!(text.starts_with("--- !tapi-tbd\n"));
/// assert!(text.contains("install-name:    '/usr/lib/libSystem.B.dylib'"));
/// assert!(text.contains("'_malloc'"));
/// ```
pub fn tbd(b: &SystemLibrary, arch: Arquitetura) -> String {
    let alvo = format!("{}-macos", arch.name());
    let own_set = match arch {
        Arquitetura::Arm64 => b.arm64_only,
        Arquitetura::X86_64 => b.x86_64_only,
    };
    let mut names: Vec<&str> = b.symbols.iter().chain(own_set).copied().collect();
    names.sort_unstable();
    let list: Vec<String> = names.iter().map(|n| format!("'{n}'")).collect();
    format!(
        "--- !tapi-tbd\ntbd-version:     4\ntargets:         [ {alvo} ]\ninstall-name:    '{}'\nexports:\n  - targets:     [ {alvo} ]\n    symbols:     [ {} ]\n...\n",
        b.install_name,
        list.join(",\n                   ")
    )
}

/// Generates in `dir` the `.tbd` files of [`SYSTEM_LIBRARIES`] for `arch`.
///
/// # Errors
///
/// A write failure in the directory.
pub fn gerar(dir: &Path, arch: Arquitetura) -> Result<(), String> {
    for b in SYSTEM_LIBRARIES {
        let path = dir.join(b.file);
        if let Some(p) = path.parent() {
            std::fs::create_dir_all(p).map_err(|e| format!("{}: {e}", p.display()))?;
        }
        std::fs::write(&path, tbd(b, arch)).map_err(|e| format!("{}: {e}", path.display()))?;
    }
    Ok(())
}

/// The fingerprint of the generated content, for the directory in the cache.
fn printing(arch: Arquitetura) -> String {
    let mut h = blake3::Hasher::new();
    for b in SYSTEM_LIBRARIES {
        h.update(b.file.as_bytes());
        h.update(tbd(b, arch).as_bytes());
    }
    h.finalize().to_hex()[..16].to_string()
}

/// The link sysroot with the `.tbd` files, and the SDK version (empty: the minimum).
#[derive(Debug, Clone)]
pub struct SysrootMacos {
    root: PathBuf,
    version: String,
}

impl SysrootMacos {
    /// The distribution one, otherwise the one in the native cache, generated now if missing.
    ///
    /// # Errors
    ///
    /// The generation failed (see [`gerar`]).
    pub fn locate() -> Result<&'static SysrootMacos, String> {
        static S: std::sync::OnceLock<Result<SysrootMacos, String>> = std::sync::OnceLock::new();
        S.get_or_init(|| {
            let arch = Arquitetura::do_hospedeiro();
            if let Some(dir) = dartforge_elements::distribuicao::em_lib(&format!("sysroot/{}", arch.triple_do_sysroot()))
                && dir.join(SYSTEM_LIBRARIES[0].file).is_file()
            {
                let version = std::fs::read_to_string(dir.join(VERSION_FILE)).unwrap_or_default().trim().to_string();
                return Ok(SysrootMacos { root: dir, version });
            }
            let root = crate::cache::native_cache_dir().join("ligacao-macos");
            let key = format!("{}-{}", arch.name(), printing(arch));
            let dir = root.join(&key);
            if dir.join("pronto").is_file() {
                return Ok(SysrootMacos { root: dir, version: String::new() });
            }
            let tmp = root.join(format!("{key}.tmp.{}", std::process::id()));
            let _ = std::fs::remove_dir_all(&tmp);
            gerar(&tmp, arch)?;
            std::fs::write(tmp.join("pronto"), b"").map_err(|e| e.to_string())?;
            if std::fs::rename(&tmp, &dir).is_err() {
                // The destination exists. With the ready mark, another process won the
                // race: its copy counts. Without it, it is a leftover of an interrupted
                // generation or of a previous version without the mark (CI
                // restores `target/` from a cache): it goes away, and ours comes in.
                if !dir.join("pronto").is_file() {
                    let _ = std::fs::remove_dir_all(&dir);
                    if std::fs::rename(&tmp, &dir).is_err() && !dir.join("pronto").is_file() {
                        let _ = std::fs::remove_dir_all(&tmp);
                        return Err(format!("não foi possível instalar {}", dir.display()));
                    }
                }
                let _ = std::fs::remove_dir_all(&tmp);
            }
            Ok(SysrootMacos { root: dir, version: String::new() })
        })
        .as_ref()
        .map_err(Clone::clone)
    }
}

/// What gets linked.
pub enum Product<'a> {
    /// An executable.
    Executable,
    /// A dynamic library with the given `install_name`, exporting (and
    /// pulling from the `staticlib`s) the given symbols.
    Dynamic { install_name: &'a str, exported: &'a [String] },
}

/// A link through `ld64.lld`.
pub struct Linkage<'a> {
    pub product: Product<'a>,
    /// Objects and libraries of the program, in order.
    pub entries: Vec<PathBuf>,
    /// Look for the dynamic libraries next to the executable.
    pub executable_rpath: bool,
    /// LTO of the input bitcodes (production).
    pub lto: bool,
    /// The target CPU of the LTO code generation (`--cpu`, the LLVM name);
    /// `None`, the baseline.
    pub cpu: Option<&'static str>,
    /// Strip what nothing reaches (`-dead_strip`) and the local symbols (production).
    pub prune: bool,
    /// Keep the debug map even when pruning (J05).
    pub keep_debug_info: bool,
    pub exit: &'a Path,
}

/// `ld64.lld`: the distribution one, the one next to Clang, or the one on `PATH`.
pub fn ld64_lld(clang: &Path) -> PathBuf {
    if let Some(l) = dartforge_elements::distribuicao::ferramenta_llvm("ld64.lld") {
        return l;
    }
    let alongside = clang.with_file_name("ld64.lld");
    if alongside.is_file() { alongside } else { PathBuf::from("ld64.lld") }
}

/// Links with `ld64.lld` and the `.tbd` files of the sysroot.
///
/// # Errors
///
/// `ld64.lld` did not run or rejected the link (the message carries what it
/// said).
pub fn link(ld: &Path, sysroot: &SysrootMacos, l: &Linkage<'_>) -> Result<(), String> {
    let arch = Arquitetura::do_hospedeiro();
    let minimum =
        std::env::var("MACOSX_DEPLOYMENT_TARGET").ok().filter(|v| !v.is_empty()).unwrap_or_else(|| arch.minimum().to_string());
    let sdk_version = if sysroot.version.is_empty() { minimum.clone() } else { sysroot.version.clone() };
    let mut cmd = Command::new(ld);
    cmd.args(["-arch", arch.name(), "-platform_version", "macos", &minimum, &sdk_version]);
    cmd.arg("-syslibroot").arg(&sysroot.root);
    match &l.product {
        Product::Executable => {
            cmd.args(["-execute", "-dynamic"]);
        }
        Product::Dynamic { install_name, exported } => {
            cmd.args(["-dylib", "-install_name", install_name]);
            let mut rsp = String::new();
            for n in exported.iter() {
                rsp.push_str(&format!("-u _{n}\n"));
            }
            let file = l.exit.with_extension("rsp");
            std::fs::write(&file, rsp).map_err(|e| format!("{}: {e}", file.display()))?;
            cmd.arg(format!("@{}", file.display()));
        }
    }
    cmd.arg("-o").arg(l.exit);
    if l.executable_rpath {
        cmd.args(["-rpath", "@executable_path"]);
    }
    if l.lto {
        cmd.arg(format!("--lto-O{}", crate::driver::lto_level()));
        // Roots by maps: `ld64.lld` does not split the ThinLTO indices
        // (no `--thinlto-index-only`), so the maps pass runs in its
        // LTO, at the end of the optimization of each module — after the inlining
        // between the program and the SDK —, followed by the verifier
        // (docs/NATIVO-MAPAS-DE-PILHA-E-EXCECOES.md §3.4, Step 4). The map
        // comes out in the LLVM format and the `.no_dead_strip` of each module
        // keeps it from `-dead_strip` (`llvm/mod.rs`).
        if crate::alvo::raizes_por_mapas().unwrap_or(false) {
            let level = crate::driver::lto_level().max(1);
            // The roots stay in the slot (the LLVM default), not in the preserved
            // register as in the embedded generator: here RS4GC runs inside
            // the linker's LTO, without the cleanup of the static addresses of the
            // `"deopt"` (`dartforge_llvm`, `tirar_estaticos_do_deopt`), and
            // with them in registers the code generator may fail
            // (docs/NATIVO-MAPAS-DE-PILHA-E-EXCECOES.md §14.12).
            cmd.arg(format!("--lto-newpm-passes=lto<O{level}>,rewrite-statepoints-for-gc,verify"));
        }
        cmd.arg(format!("--thinlto-jobs={}", crate::driver::generation_tasks()));
        // The outliner (`driver::outliner_at_link`) is a global LLVM option,
        // which the ThinLTO cache key does not see: the modules generated with it
        // stay in a separate cache.
        let outliner = crate::driver::outliner_at_link();
        if outliner {
            cmd.arg("-mllvm").arg("-enable-machine-outliner=always");
        }
        if let Some(d) = crate::driver::thinlto_cache() {
            let d = if outliner { d.join("outliner") } else { d };
            if std::fs::create_dir_all(&d).is_ok() {
                cmd.arg("-cache_path_lto").arg(d);
            }
        }
        if let Some(c) = l.cpu {
            cmd.arg("-mllvm").arg(format!("-mcpu={c}"));
        }
        // Measurement: LLVM options for the LTO (`DARTFORGE_LTO_MLLVM="-a -b=1"`,
        // as on Windows). The ThinLTO cache does not see them in the key: measure with
        // `DARTFORGE_SEM_CACHE_THINLTO=1`.
        if let Ok(v) = std::env::var("DARTFORGE_LTO_MLLVM") {
            for o in v.split_whitespace() {
                cmd.arg("-mllvm").arg(o);
            }
        }
    }
    if l.prune {
        cmd.arg("-dead_strip");
        // Without `--icf=safe` (which `ld64.lld` has, like `ld.lld` and
        // `lld-link`): it was not verified on a Mac that it treats as taken
        // every address of an object without `__llvm_addrsig` (the Rust ones), and
        // the `==` of tear-offs depends on that (`ligador_windows.rs`).
        // `-S` strips the debug map (J05); `-x`, the local symbols.
        if !crate::ligador::keep_symbols() && !l.keep_debug_info {
            cmd.args(["-S", "-x"]);
        }
        // The production executable exports nothing: nobody loads it nor
        // looks a symbol up in it (the runtime's `dlsym` and
        // `DynamicLibrary.process()` look at the system libraries). Without
        // this, every function and every global constant of the program (the `weak`
        // ones of the images, `linkonce_odr`) went into the export trie, into the
        // symbol table (`-x` only strips the local ones) and into the weak binding
        // that dyld redoes on every load: 6.5 MB of `new_sali/backend`.
        // The unexported symbols become local and `-x` strips them; with
        // `DARTFORGE_MANTER_SIMBOLOS=1` they stay, for profiling.
        if matches!(l.product, Product::Executable) {
            cmd.arg("-no_exported_symbols");
        }
    }
    if l.prune
        && let Some(m) = crate::ligador::link_map(l.exit)
    {
        cmd.arg("-map").arg(m);
    }
    cmd.args(&l.entries);
    cmd.args(LIBRARIES);
    let exit = cmd.output().map_err(|e| format!("falha ao executar {}: {e}", ld.display()))?;
    if !exit.status.success() {
        let text = String::from_utf8_lossy(&exit.stderr);
        // The errors (and the `>>>` lines that explain them) before the warnings: with
        // many objects, the minimum-version warnings hid the error.
        let (errors, avisos): (Vec<&str>, Vec<&str>) =
            text.lines().filter(|l| !l.trim().is_empty()).partition(|l| !l.contains("warning:"));
        let n_warnings = 40usize.saturating_sub(errors.len());
        let lines: Vec<&str> = errors.into_iter().chain(avisos.into_iter().take(n_warnings)).collect();
        return Err(format!("o ld64.lld falhou na ligação ({}):\n{}", exit.status, lines.join("\n")));
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn no_repeated_symbol() {
        for arch in [Arquitetura::Arm64, Arquitetura::X86_64] {
            let mut all: Vec<&str> = Vec::new();
            for b in SYSTEM_LIBRARIES {
                all.extend(b.symbols);
                all.extend(if arch == Arquitetura::Arm64 { b.arm64_only } else { b.x86_64_only });
            }
            let total = all.len();
            all.sort_unstable();
            all.dedup();
            assert_eq!(all.len(), total, "{arch:?}");
        }
    }

    #[test]
    fn tbd_by_architecture() {
        let arm = tbd(&SYSTEM_LIBRARIES[0], Arquitetura::Arm64);
        let x86 = tbd(&SYSTEM_LIBRARIES[0], Arquitetura::X86_64);
        assert!(arm.contains("targets:         [ arm64-macos ]") && arm.contains("'_stat'") && !arm.contains("INODE64"));
        assert!(x86.contains("targets:         [ x86_64-macos ]") && x86.contains("'_stat$INODE64'") && !x86.contains("'_stat'"));
        assert!(arm.ends_with("...\n"));
    }

    #[test]
    fn generate_writes_each_library() {
        let dir = tempfile::tempdir().unwrap();
        gerar(dir.path(), Arquitetura::Arm64).unwrap();
        for b in SYSTEM_LIBRARIES {
            let text = std::fs::read_to_string(dir.path().join(b.file)).unwrap();
            assert!(text.contains(b.install_name));
        }
    }

    /// The `.tbd` files (relative to the SDK root) of the libraries cited in a `.tbd`
    /// that are not documents of the file itself (`ld64.lld` looks up a
    /// reexport by the install path inside the `-syslibroot`).
    #[cfg(target_os = "macos")]
    fn external_reexports(text: &str) -> Vec<String> {
        let own_set: Vec<&str> = text
            .lines()
            .filter_map(|l| l.trim().strip_prefix("install-name:"))
            .map(|v| v.trim().trim_matches(|c| c == '\'' || c == '"'))
            .collect();
        let mut exit = Vec::new();
        for chunk in text.split(['\'', '"', ' ', ',', '[', ']', '\n']) {
            let path = chunk.trim();
            if !(path.starts_with("/usr/lib/") || path.starts_with("/System/Library/")) || own_set.contains(&path) {
                continue;
            }
            let rel = path.trim_start_matches('/');
            let tbd = match rel.strip_suffix(".dylib") {
                Some(base) => format!("{base}.tbd"),
                None => format!("{rel}.tbd"),
            };
            if !exit.contains(&tbd) {
                exit.push(tbd);
            }
        }
        exit
    }

    /// The names that an SDK `.tbd` and the ones it reexports from other
    /// files cite (every word: enough to check existence).
    #[cfg(target_os = "macos")]
    fn names_in_sdk(root: &Path, file: &str) -> std::collections::HashSet<String> {
        let mut names = std::collections::HashSet::new();
        let mut pending_set = vec![file.to_string()];
        let mut seen_set = std::collections::HashSet::new();
        while let Some(rel) = pending_set.pop() {
            if !seen_set.insert(rel.clone()) {
                continue;
            }
            let Ok(text) = std::fs::read_to_string(root.join(&rel)) else { continue };
            names.extend(text.split(['\'', '"', ' ', ',', '[', ']', '\n']).map(|p| p.trim().to_string()));
            pending_set.extend(external_reexports(&text));
        }
        names
    }

    /// Each generated name exists in the SDK `.tbd` of the same library (the
    /// macOS runner, with Xcode or the Command Line Tools).
    #[cfg(target_os = "macos")]
    #[test]
    fn symbols_exist_in_sdk() {
        let root = crate::alvo::macos_sdk_root().expect("SDK do macOS (xcrun)");
        let mut missing_set = Vec::new();
        for b in SYSTEM_LIBRARIES {
            let names = names_in_sdk(root, b.file);
            assert!(names.contains(b.install_name), "{}: install-name {} fora do SDK", b.file, b.install_name);
            let own_set = if Arquitetura::do_hospedeiro() == Arquitetura::Arm64 { b.arm64_only } else { b.x86_64_only };
            for n in b.symbols.iter().chain(own_set) {
                if !names.contains(*n) {
                    missing_set.push(format!("{}: {n}", b.file));
                }
            }
        }
        assert!(missing_set.is_empty(), "não exportados pelo SDK: {missing_set:#?}");
    }

    /// The two runtime `staticlib`s link only with the generated `.tbd` files, with
    /// everything a program may pull from them: each name the generated code
    /// calls (`dartforge_runtime::symbols::NAMES`, like the source SDK library
    /// in `sdk_modulo.rs`) is required with `-u`. The `aot` one (with the `main`)
    /// becomes an executable and the `dll` one, a dynamic library; the `dartforge_entry` of the
    /// generated code comes from a C object. A name outside
    /// [`SYSTEM_LIBRARIES`] makes `ld64.lld` reject the link, and its
    /// message lists all of them (`--error-limit=0`). (Apple's `nm` does not read
    /// dartforge's LLVM bitcode that goes into the `staticlib`s; and
    /// `-all_load` would require even what no program links, like the
    /// SecureTransport of `security_framework`.)
    #[cfg(target_os = "macos")]
    #[test]
    fn runtime_only_uses_listed_symbols() {
        let clang = crate::driver::NativeDriverOptions::default().clang;
        let dir = tempfile::tempdir().unwrap();
        gerar(&dir.path().join("sysroot"), Arquitetura::do_hospedeiro()).unwrap();
        let sysroot = SysrootMacos { root: dir.path().join("sysroot"), version: String::new() };
        let c = dir.path().join("entrada.c");
        std::fs::write(&c, "void dartforge_entry(void) {}\n").unwrap();
        let obj = dir.path().join("entrada.o");
        let status = Command::new(&clang).arg("-c").arg(&c).arg("-o").arg(&obj).status().expect("executar o Clang");
        assert!(status.success(), "o Clang não compilou {}", c.display());
        let exe = dir.path().join("programa");
        let dylib = dir.path().join("libteste.dylib");
        let cases = [
            (crate::cache::RuntimeCache::get_or_compile(), Product::Executable, &exe),
            (
                crate::cache::RuntimeCache::para_dll(),
                Product::Dynamic { install_name: "@rpath/libteste.dylib", exported: &[] },
                &dylib,
            ),
        ];
        for (lib, product, exit) in cases {
            let lib = lib.expect("runtime pré-compilado").lib_path;
            let mut entries = vec![PathBuf::from("--error-limit=0"), obj.clone()];
            for n in dartforge_runtime::simbolos::NOMES.iter().filter(|n| **n != "main") {
                entries.push(PathBuf::from("-u"));
                entries.push(PathBuf::from(format!("_{n}")));
            }
            entries.push(lib);
            let l = Linkage { product, entries, executable_rpath: false, lto: false, cpu: None, prune: false, keep_debug_info: false, exit };
            if let Err(e) = link(&ld64_lld(&clang), &sysroot, &l) {
                panic!("o runtime usa nomes fora de BIBLIOTECAS_DO_SISTEMA:\n{e}");
            }
        }
        // The executable runs (only the empty `dartforge_entry`).
        let exit = Command::new(&exe).output().expect("executar o programa");
        assert!(exit.status.code().is_some(), "o programa terminou por sinal: {exit:?}");
    }
}
